#define GFS_CURVED_TOPOLOGY_LIBRARY
#include "test_curved_topology_v1.cpp"
int main(int argc,char **argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==2,"new fixture output");curved::Packet p={};p.parameters[1]=5./3;p.parameters[2]=1e-3;p.parameters[3]=2;p.parameters[4]=2;p.parameters[5]=8;p.parameters[6]=1;p.parameters[7]=1e-6;p.parameters[8]=.25;p.parameters[9]=0;p.cells=1;p.record.resize(1);auto &r=p.record[0];r.cell=102;r.component=0;r.map.n=12;r.scale[0]=r.scale[1]=1;r.triangle.geometry.x[0][0]=r.triangle.geometry.x[0][1]=0;r.triangle.geometry.x[1][0]=1;r.triangle.geometry.x[1][1]=0;r.triangle.geometry.x[2][0]=0;r.triangle.geometry.x[2][1]=1;need(gfs_material_triangle_init(&r.triangle.geometry),"positive manufactured source triangle");
    for(int a=0;a<10;a++){double x[2];gfs_material_p3_node(&r.triangle,a,x);r.map.x[0][a]=x[0]+.05*x[1]*x[1];r.map.x[1][a]=x[1];r.map.v[0][a]=.1;r.map.v[1][a]=.2;double Dq[4];need(gfs_material_p3_radial_remainder(r.triangle.geometry.x[0],x[0],x[1],p.parameters[3],r.triangle.remainder[a],Dq),"manufactured initial basis domain");}
    R ax=.31L+.05L*.27L*.27L,ay=.27L,delta=1e-4L,d=.1L,root3=sqrtl(3.L);std::vector<curved_partition::Site> site={{101,ax,ay},{102,ax+d,ay},{103,ax-d/2,ay+d*root3/2},{104,ax-d/2,ay-d*root3/2}};std::vector<R> weight={0,d*d-2*d*delta,d*d-2*d*delta,d*d-2*d*delta};
    auto started=std::chrono::steady_clock::now();auto coarse=integrate(0,p,site,weight,12,10,nullptr);std::vector<curved_topology::Panel> leaves;auto guard=certify_topology(0,p,site,weight,leaves);Moment total[24]={};for(const auto &g:leaves){std::vector<R> interval={g.low,g.high};auto q=integrate(0,p,site,weight,16,16,nullptr,&interval);for(int j=0;j<4;j++)sum(total[j],q.target[j]);}
    R exact=3*root3*delta*delta,error=fabsl(total[0].a[VOLUME]-exact);std::string path=std::string(argv[1])+"/radial_panels.csv";FILE *f=fopen(path.c_str(),"w");need(f,"lens fixture event panels");fprintf(f,"low,high,depth,stable,mass_bound,K_bound\n");for(auto g:leaves)fprintf(f,"%.21Lg,%.21Lg,%d,%d,%.21Lg,%.21Lg\n",g.low,g.high,g.depth,g.stable,g.mass_bound,g.K_bound);fclose(f);double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();
    printf("{\"scope\":\"real Laguerre tiny closed target cell inside a curved J=1 material triangle; fixed radial nodes can miss the entire cell; event guard fixture only, not a Kepler result\",\"exact_area\":%.17Lg,\"coarse_target_area\":%.17Lg,\"guarded_target_area\":%.17Lg,\"absolute_area_error\":%.17Lg,\"guard_complete\":%s,\"evaluations\":%llu,\"leaves\":%zu,\"event_mass_bound\":%.17Lg,\"event_K_bound\":%.17Lg,\"seconds\":%.17g}\n",exact,coarse.target[0].a[VOLUME],total[0].a[VOLUME],error,guard.complete?"true":"false",(unsigned long long)guard.evaluations,leaves.size(),guard.mass_bound,guard.K_bound,seconds);
    need(coarse.target[0].a[VOLUME]<exact*.1L,"coarse radial fixture actually misses the tiny target cell");need(total[0].a[VOLUME]>exact*.9L && error<1e-11L,"closed target cell detected and integrated");active_mpi=false;MPI_Finalize();return 0;
}
